package audio.tembra.engine.perf

import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertFalse

/**
 * `PerfBuild.PERF_ENABLED` is generated by the `generatePerfBuild` Gradle task from the
 * `tembra.perf` property: `false` in the default build, `true` in measurement builds. The task
 * writes the same answer into `PerfBuildExpectation` for this test run, so the test proves the
 * property reaches the generated constant on every target (JVM and the iOS simulator alike).
 */
class PerfBuildTest {

    @Test
    fun perfEnabledFollowsTheGradleProperty() {
        assertEquals(PerfBuildExpectation.PERF_ENABLED, PerfBuild.PERF_ENABLED)
    }

    @Test
    fun defaultBuildIsNotAMeasurementBuild() {
        if (!PerfBuildExpectation.PERF_ENABLED) {
            assertFalse(PerfBuild.PERF_ENABLED, "PERF_ENABLED must be false without -Ptembra.perf")
        }
    }
}
